  // Combina la somma senza carry con Cin per ottenere la somma finale
  io.Sum := sumXOR ^ io.Cin

  // Assegna il carry out totale all'uscita Cout
  io.Cout := totalCarry
}

object FullAdder1Bit extends App {
  Driver.execute(args, () => new FullAdder1Bit)
}
